    correction: [{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">x - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √3 = √2</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2 - √3</span>"},{"quoi":"نحدّد الإشارة","math":"العدد <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2 - √3</span> هو عدد موجب تقريبا يساوي 2.35"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد موجب هي هو نفسه، و لعدد سالب هي مقابله"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">|x| = <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2 - √3</span>"}],
