    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - 3 + √2 - 2 + x - 2x + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = (x - 2x) + (-<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - 3 - 2 + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span>) + √2</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -x - 5 + √2</span>"}],
