    correction: [{"quoi":"نترجم المعطى","math":"عددان متقابلان مجموعهما منعدم<span dir=\"ltr\" class=\"expr\">: E = -(<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - √2)</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-x - 5 + √2 = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">-x = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2 - (-5 + √2)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2 - (-5 + √2) = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span></span>"}],
