    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">F = -3 + b - 2 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + a + b + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - π - b + <span class=\"frac\"><span class=\"num\">31</span><span class=\"den\">6</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = a + (b + b - b) + (-3 - 2 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">31</span><span class=\"den\">6</span></span>) - π</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = a + b + 2 - π</span>"}],
