    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">[x + 1] - [-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + (x - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>)] - [<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">5</span></span> + 3] + x - <span class=\"frac\"><span class=\"num\">39</span><span class=\"den\">10</span></span> - π = x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> - π</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> - π = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span></span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> - (-<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> - π)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> - (-<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> - π) = <span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span> + π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span> + π</span>"}],
