    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - [-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - (π + y)] - y + y = y - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + π</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">y - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + π = -3 - π</span>"},{"quoi":"نعزل y","math":"<span dir=\"ltr\" class=\"expr\">y = -3 - π - (-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + π)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-3 - π - (-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + π) = -<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">6</span></span> - 2π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y = -<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">6</span></span> - 2π</span>"}],
