    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">a + [<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + (<span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √3)] - [√3 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - 4] - <span class=\"frac\"><span class=\"num\">142</span><span class=\"den\">15</span></span> - √3 = a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - √3</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - √3 = 4 + √3</span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">a = 4 + √3 - (-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - √3)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">4 + √3 - (-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - √3) = <span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">2</span></span> + 2√3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">2</span></span> + 2√3</span>"}],
