    correction: [{"quoi":"نترجم المعطى","math":"متساويان يعني أنّ فرقهما منعدم<span dir=\"ltr\" class=\"expr\">: M - N = 0</span>"},{"quoi":"نطرح الشكلين المختصرين","math":"<span dir=\"ltr\" class=\"expr\">M - N = -a + b - 5 + √2 + π</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-a + b - 5 + √2 + π = 0</span>"},{"quoi":"نعزل حدود الحرفين","math":"<span dir=\"ltr\" class=\"expr\">-a + b = 5 - √2 - π</span>"},{"quoi":"نقسم على المعامل","math":"<span dir=\"ltr\" class=\"expr\">a - b = -5 + √2 + π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a - b = -5 + √2 + π</span>"}],
